#[tokio::test]
async fn mark_viewed() {
    let api = support::MockApi::start(vec![support::Reply::status(204)]).await;
    let params: types::ChannelsMarkViewedParams = support::from_json(r#"{"channelMessageIds":["channelMessageIds 1"]}"#);
    api.client().channels().mark_viewed("k57a8m2x9d3f0q1wjh6ypc4n2d7s0vbr", "120363198765432101@newsletter", params).await.unwrap();
    let calls = api.calls().await;
    assert_eq!(calls.len(), 1);
    assert_eq!(calls[0].method, "POST");
    assert_eq!(calls[0].path, "/v1/accounts/k57a8m2x9d3f0q1wjh6ypc4n2d7s0vbr/channels/120363198765432101%40newsletter/mark-viewed");
    assert_eq!(calls[0].query, support::pairs(&[]));
    support::assert_json(&calls[0].body, &support::json(r#"{"channelMessageIds":["channelMessageIds 1"]}"#));
    assert!(calls[0].header(sdk::IDEMPOTENCY_HEADER).is_some_and(|key| !key.is_empty()));
}

#[tokio::test]
async fn mark_viewed_retries_with_one_key() {
    let api = support::MockApi::start(vec![support::Reply::status(503), support::Reply::status(204)]).await;
    let params: types::ChannelsMarkViewedParams = support::from_json(r#"{"channelMessageIds":["channelMessageIds 1"]}"#);
    api.client().channels().mark_viewed("k57a8m2x9d3f0q1wjh6ypc4n2d7s0vbr", "120363198765432101@newsletter", params).await.unwrap();
    let calls = api.calls().await;
    assert_eq!(calls.len(), 2);
    let key = calls[0].header(sdk::IDEMPOTENCY_HEADER).unwrap();
    assert!(!key.is_empty());
    assert_eq!(calls[1].header(sdk::IDEMPOTENCY_HEADER), Some(key));
    assert_eq!(calls[0].body, calls[1].body);
}
